import type { ChartColor } from "./LineChart";

export interface ChartLegendProps {
  series: { name: string; color: ChartColor }[];
  className?: string;
}

export function ChartLegend({ series, className }: ChartLegendProps) {
  return (
    <div
      className={["chart-legend", className].filter(Boolean).join(" ")}
      role="list">
      {series.map((s) => (
        <span key={s.name} className="chart-legend-item" role="listitem">
          <span
            className={["chart-legend-swatch", `chart-${s.color}`].join(" ")}
          />
          {s.name}
        </span>
      ))}
    </div>
  );
}
