import {
  createContext,
  useContext,
  ReactNode,
  useState,
  ReactElement,
  cloneElement,
} from "react";

interface SidebarContextValue {
  collapsed: boolean;
}

const SidebarContext = createContext<SidebarContextValue>({ collapsed: false });

export interface SidebarProps {
  children: ReactNode;
  className?: string;
  collapsed?: boolean;
  title?: string;
  onToggle?: (collapsed: boolean) => void;
}

const base = "sidebar";
const widths = {
  expanded: "sidebar-expanded",
  collapsed: "sidebar-collapsed",
};

export function Sidebar({
  children,
  className,
  collapsed: collapsedProp = false,
  title = "Sidebar",
  onToggle,
}: SidebarProps) {
  const [collapsed, setCollapsed] = useState(collapsedProp);
  const classes = [
    base,
    collapsed ? widths.collapsed : widths.expanded,
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const handleToggle = () => {
    setCollapsed((prev) => {
      const next = !prev;
      if (onToggle) onToggle(next);
      return next;
    });
  };

  return (
    <SidebarContext.Provider value={{ collapsed }}>
      <nav className={classes} aria-label={title} role="navigation">
        <button
          className="sidebar-toggler"
          onClick={handleToggle}
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}>
          {collapsed ? "»" : "«"}
        </button>
        <div className="sidebar-content">{children}</div>
      </nav>
    </SidebarContext.Provider>
  );
}

// SidebarBrand component
export function SidebarBrand({ children }: { children: ReactNode }) {
  return <div className="sidebar-brand">{children}</div>;
}

// SidebarGroup component for nested/collapsible groups
export function SidebarGroup({
  label,
  icon,
  children,
  defaultOpen = false,
  className,
}: {
  label: string;
  icon?: ReactNode;
  children: ReactNode;
  defaultOpen?: boolean;
  className?: string;
}) {
  const [open, setOpen] = useState(defaultOpen);
  const { collapsed } = useContext(SidebarContext);
  const groupClasses = [
    "sidebar-group",
    open ? "sidebar-group-open" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ");
  return (
    <div className={groupClasses}>
      <button
        className="sidebar-group-toggle"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        tabIndex={0}>
        {icon && <span className="sidebar-group-icon">{icon}</span>}
        <span className={collapsed ? "sr-only" : "sidebar-group-label"}>
          {label}
        </span>
        <span className="sidebar-group-arrow">{open ? "▼" : "▶"}</span>
      </button>
      {open && <div className="sidebar-group-items">{children}</div>}
    </div>
  );
}

export interface SidebarItemProps {
  label: string;
  icon?: ReactNode;
  href?: string;
  active?: boolean;
  onClick?: () => void;
  className?: string;
  children?: ReactNode; // for nested items
}

const itemBase = "sidebar-item";
const itemActive = "sidebar-item-active";
const iconCls = "sidebar-item-icon";
const labelCls = "sidebar-item-label";

export function SidebarItem({
  label,
  icon,
  href,
  active,
  onClick,
  className,
  children,
}: SidebarItemProps) {
  const { collapsed } = useContext(SidebarContext);
  const classes = [itemBase, active ? itemActive : null, className]
    .filter(Boolean)
    .join(" ");

  const content = (
    <>
      {icon ? <span className={iconCls}>{icon}</span> : null}
      <span className={collapsed ? "sr-only" : labelCls}>{label}</span>
    </>
  );

  // If there are nested children, render them as a nested list
  const hasChildren = !!children;

  if (href) {
    return (
      <div className={hasChildren ? "sidebar-item-nested" : undefined}>
        <a
          href={href}
          className={classes}
          aria-label={label}
          aria-current={active ? "page" : undefined}>
          {content}
        </a>
        {hasChildren && <div className="sidebar-subitems">{children}</div>}
      </div>
    );
  }

  return (
    <div className={hasChildren ? "sidebar-item-nested" : undefined}>
      <button
        type="button"
        className={classes}
        onClick={onClick}
        aria-label={label}
        aria-current={active ? "page" : undefined}>
        {content}
      </button>
      {hasChildren && <div className="sidebar-subitems">{children}</div>}
    </div>
  );
}
