import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import "./Popover.css";

export type PopoverPosition = "top" | "right" | "bottom" | "left";

export interface PopoverProps {
  content: ReactNode;
  children: ReactNode;
  position?: PopoverPosition;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  closeOnOutsideClick?: boolean;
  className?: string;
}

export const Popover = forwardRef<HTMLDivElement, PopoverProps>(
  function Popover(
    {
      content,
      children,
      position = "bottom",
      open,
      defaultOpen = false,
      onOpenChange,
      closeOnOutsideClick = true,
      className,
    },
    ref,
  ) {
    const [internalOpen, setInternalOpen] = useState(defaultOpen);
    const isControlled = open !== undefined;
    const isOpen = isControlled ? open : internalOpen;
    const rootRef = useRef<HTMLDivElement | null>(null);

    const setOpen = useCallback(
      (next: boolean) => {
        if (!isControlled) setInternalOpen(next);
        onOpenChange?.(next);
      },
      [isControlled, onOpenChange],
    );

    const combineRef = useCallback(
      (node: HTMLDivElement | null) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      },
      [ref],
    );

    useEffect(() => {
      if (!isOpen || !closeOnOutsideClick) return;
      const onPointerDown = (e: PointerEvent) => {
        if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
          setOpen(false);
        }
      };
      const onKeyDown = (e: KeyboardEvent) => {
        if (e.key === "Escape") setOpen(false);
      };
      document.addEventListener("pointerdown", onPointerDown);
      document.addEventListener("keydown", onKeyDown);
      return () => {
        document.removeEventListener("pointerdown", onPointerDown);
        document.removeEventListener("keydown", onKeyDown);
      };
    }, [isOpen, setOpen, closeOnOutsideClick]);

    return (
      <div
        ref={combineRef}
        className={["popover", className].filter(Boolean).join(" ")}>
        <span
          className="popover-trigger"
          aria-haspopup="dialog"
          aria-expanded={isOpen}
          onClick={() => setOpen(!isOpen)}>
          {children}
        </span>
        {isOpen ? (
          <div role="dialog" className={`popover-popup popover-${position}`}>
            {content}
          </div>
        ) : null}
      </div>
    );
  },
);
