import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import "./Skeleton.css";

export type SkeletonVariant = "text" | "circular" | "rectangular" | "rounded";
export type SkeletonAnimation = "pulse" | "wave" | "none";

export interface SkeletonProps extends HTMLAttributes<HTMLDivElement> {
  variant?: SkeletonVariant;
  width?: number | string;
  height?: number | string;
  animation?: SkeletonAnimation;
  lines?: number;
  lastLineWidth?: number | string;
  decorative?: boolean;
  className?: string;
}

const animationClass = (animation: SkeletonAnimation) =>
  animation === "none" ? "skeleton-static" : `skeleton-${animation}`;

export const Skeleton = forwardRef<HTMLDivElement, SkeletonProps>(
  function Skeleton(
    {
      variant = "text",
      width,
      height,
      animation = "pulse",
      lines,
      lastLineWidth = "60%",
      decorative = false,
      className,
      style,
      ...props
    },
    ref,
  ) {
    const singleStyle: CSSProperties = {
      ...(width !== undefined ? { width } : {}),
      ...(height !== undefined ? { height } : {}),
      ...style,
    };

    const count = lines && lines > 1 ? lines : undefined;
    const srLabel = !decorative ? (
      <span className="sr-only">Loading</span>
    ) : null;

    if (count) {
      return (
        <div
          ref={ref}
          role={decorative ? undefined : "status"}
          aria-hidden={decorative || undefined}
          className={["skeleton-group", className].filter(Boolean).join(" ")}
          {...props}>
          {Array.from({ length: count }, (_, i) => (
            <div
              key={i}
              className={[
                "skeleton",
                "skeleton-text",
                animationClass(animation),
              ]
                .filter(Boolean)
                .join(" ")}
              style={i === count - 1 ? { width: lastLineWidth } : undefined}
            />
          ))}
          {srLabel}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        role={decorative ? undefined : "status"}
        aria-hidden={decorative || undefined}
        className={[
          "skeleton",
          `skeleton-${variant}`,
          animationClass(animation),
          className,
        ]
          .filter(Boolean)
          .join(" ")}
        style={singleStyle}
        {...props}>
        {srLabel}
      </div>
    );
  },
);
