export type ToastType = "success" | "error" | "warning" | "info";

export type ToastPosition =
  | "top-right"
  | "top-left"
  | "bottom-right"
  | "bottom-left"
  | "top-center"
  | "bottom-center";

export interface ToastItem {
  id: number;
  type: ToastType;
  message: string;
  title?: string;
  duration: number;
}

export interface ToastOptions {
  title?: string;
  /** Auto-dismiss delay in ms. 0 = sticky. Default 4000. */
  duration?: number;
}

export interface ToastState {
  success: (message: string, options?: ToastOptions) => number;
  error: (message: string, options?: ToastOptions) => number;
  warning: (message: string, options?: ToastOptions) => number;
  info: (message: string, options?: ToastOptions) => number;
  dismiss: (id: number) => void;
  dismissAll: () => void;
}

let toasts: ToastItem[] = [];
let nextId = 1;
const listeners = new Set<(items: ToastItem[]) => void>();

function emit() {
  listeners.forEach((fn) => fn([...toasts]));
}

function addToast(
  type: ToastType,
  message: string,
  options?: ToastOptions,
): number {
  const id = nextId++;
  const duration = options?.duration ?? 4000;
  toasts = [...toasts, { id, type, message, title: options?.title, duration }];
  emit();
  if (duration > 0) {
    window.setTimeout(() => removeToast(id), duration);
  }
  return id;
}

export function removeToast(id: number) {
  toasts = toasts.filter((t) => t.id !== id);
  emit();
}

export function clearAllToasts() {
  toasts = [];
  emit();
}

export function subscribeToasts(fn: (items: ToastItem[]) => void): () => void {
  listeners.add(fn);
  fn([...toasts]);
  return () => {
    listeners.delete(fn);
  };
}

/** Imperative toast API. Requires a mounted `<ToastProvider>` to render. */
export const toast: ToastState = {
  success: (message, options) => addToast("success", message, options),
  error: (message, options) => addToast("error", message, options),
  warning: (message, options) => addToast("warning", message, options),
  info: (message, options) => addToast("info", message, options),
  dismiss: removeToast,
  dismissAll: clearAllToasts,
};
