import type { ReactNode } from "react";

export type StatColor =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "danger"
  | "info"
  | "dark"
  | "light";

export type StatSize = "sm" | "md" | "lg";

export interface StatProps {
  label: string;
  value: ReactNode;
  /** Optional icon rendered in a colored bubble. */
  icon?: ReactNode;
  /** Percent change; positive = up (green), negative = down (red). */
  trend?: number;
  color?: StatColor;
  size?: StatSize;
  className?: string;
}

export function Stat({
  label,
  value,
  icon,
  trend,
  color = "primary",
  size = "md",
  className,
}: StatProps) {
  const up = (trend ?? 0) >= 0;
  return (
    <div
      className={["stat", `stat-${size}`, `stat-${color}`, className]
        .filter(Boolean)
        .join(" ")}>
      {icon && <div className="stat-icon">{icon}</div>}
      <div className="stat-body">
        <div className="stat-label">{label}</div>
        <div className="stat-value">{value}</div>
        {trend !== undefined && (
          <div
            className={
              up ? "stat-trend stat-trend-up" : "stat-trend stat-trend-down"
            }>
            <span className="stat-trend-arrow" aria-hidden="true">
              {up ? "▲" : "▼"}
            </span>
            {Math.abs(trend)}%
          </div>
        )}
      </div>
    </div>
  );
}
