import { forwardRef, type SVGProps } from "react";
import type { IconProps, IconVariants } from "./types";

/**
 * Build an icon component from thin-stroke outline geometry.
 *
 * Icons are 24×24 stroke SVGs that inherit `currentColor`, so they adapt to
 * the active light/dark theme automatically.
 */
export function createIcon(name: string, variants: IconVariants) {
  const Icon = forwardRef<SVGSVGElement, IconProps>(function Icon(
    { size = 24, strokeWidth = 1.5, className, style, ...rest },
    ref,
  ) {
    const label = rest["aria-label"];
    const base: SVGProps<SVGSVGElement> & {
      ref?: React.Ref<SVGSVGElement>;
    } = {
      ref,
      width: size,
      height: size,
      viewBox: "0 0 24 24",
      className: ["ntk-icon", className].filter(Boolean).join(" "),
      style,
      ...(label
        ? { role: "img" as const, "aria-label": label }
        : { "aria-hidden": true as const }),
      ...rest,
    };

    return (
      <svg
        {...base}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round">
        {variants.outline}
      </svg>
    );
  });

  Icon.displayName = name;
  return Icon;
}
