import {
  forwardRef,
  TextareaHTMLAttributes,
  useCallback,
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
} from "react";
import "./Textarea.css";

export type TextareaSize = "sm" | "md" | "lg";
export type TextareaResize = "none" | "vertical" | "horizontal" | "both";

export interface TextareaProps extends Omit<
  TextareaHTMLAttributes<HTMLTextAreaElement>,
  "size"
> {
  label?: string;
  size?: TextareaSize;
  resize?: TextareaResize;
  autoResize?: boolean;
  maxRows?: number;
  error?: boolean;
  errorText?: string;
  helperText?: string;
  characterCount?: boolean;
  className?: string;
}

const sizes: Record<TextareaSize, string> = {
  sm: "notched-sm",
  md: "notched-md",
  lg: "notched-lg",
};

const resizeClasses: Record<TextareaResize, string> = {
  none: "textarea-resize-none",
  vertical: "textarea-resize-vertical",
  horizontal: "textarea-resize-horizontal",
  both: "textarea-resize-both",
};

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(
  function Textarea(
    {
      label,
      size = "md",
      resize = "vertical",
      autoResize = false,
      maxRows,
      error = false,
      errorText,
      helperText,
      characterCount = false,
      className,
      rows = 4,
      maxLength,
      value,
      defaultValue,
      onChange,
      ...props
    },
    ref,
  ) {
    const innerRef = useRef<HTMLTextAreaElement | null>(null);
    const [count, setCount] = useState<number>(() =>
      typeof value === "string"
        ? value.length
        : typeof defaultValue === "string"
          ? defaultValue.length
          : 0,
    );

    const combineRef = useCallback(
      (node: HTMLTextAreaElement | null) => {
        innerRef.current = node;
        if (typeof ref === "function") {
          ref(node);
        } else if (ref) {
          ref.current = node;
        }
      },
      [ref],
    );

    const applyAutoResize = useCallback(() => {
      const el = innerRef.current;
      if (!el || !autoResize) return;
      el.style.height = "auto";
      const style = window.getComputedStyle(el);
      const lineHeight =
        parseFloat(style.lineHeight) || parseFloat(style.fontSize) * 1.5 || 21;
      const maxHeight = maxRows ? lineHeight * maxRows : undefined;
      el.style.height = `${
        maxHeight ? Math.min(el.scrollHeight, maxHeight) : el.scrollHeight
      }px`;
    }, [autoResize, maxRows]);

    useEffect(() => {
      applyAutoResize();
    }, [value, applyAutoResize]);

    const handleChange = (e: ChangeEvent<HTMLTextAreaElement>) => {
      setCount(e.target.value.length);
      applyAutoResize();
      onChange?.(e);
    };

    const metaText = error ? errorText : helperText;
    const showMeta = Boolean(metaText || characterCount);

    return (
      <div className="textarea-field">
        <fieldset
          className={[
            "notched-fieldset",
            sizes[size],
            error ? "notched-error" : "",
            className,
          ]
            .filter(Boolean)
            .join(" ")}>
          {label ? (
            <legend className="notched-label">
              <span className="notched-label-text">{label}</span>
            </legend>
          ) : null}
          <textarea
            ref={combineRef}
            className={["textarea", resizeClasses[resize]]
              .filter(Boolean)
              .join(" ")}
            rows={rows}
            maxLength={maxLength}
            value={value}
            defaultValue={defaultValue}
            aria-invalid={error || undefined}
            onChange={handleChange}
            {...props}
          />
        </fieldset>
        {showMeta ? (
          <div className="textarea-meta">
            <span
              className={
                error
                  ? "textarea-helper textarea-helper-error"
                  : "textarea-helper"
              }>
              {metaText}
            </span>
            {characterCount && maxLength ? (
              <span className="textarea-count">
                {count}/{maxLength}
              </span>
            ) : null}
          </div>
        ) : null}
      </div>
    );
  },
);
