import {
  forwardRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import "./Divider.css";

export type DividerOrientation = "horizontal" | "vertical";
export type DividerVariant =
  | "solid"
  | "dashed"
  | "dotted"
  | "double"
  | "gradient";

export interface DividerProps extends HTMLAttributes<HTMLDivElement> {
  orientation?: DividerOrientation;
  variant?: DividerVariant;
  spacing?: number | string;
  color?: string;
  withText?: boolean;
  className?: string;
  children?: ReactNode;
}

export const Divider = forwardRef<HTMLDivElement, DividerProps>(
  function Divider(
    {
      orientation = "horizontal",
      variant = "solid",
      spacing,
      color,
      withText = false,
      className,
      children,
      style,
      ...props
    },
    ref,
  ) {
    const mergedStyle: CSSProperties = {
      ...(spacing !== undefined ? { margin: spacing } : {}),
      ...(color ? ({ "--divider-color": color } as CSSProperties) : {}),
      ...style,
    };

    const classes = [
      "divider",
      `divider-${orientation}`,
      `divider-${variant}`,
      withText ? "divider-with-text" : "",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <div
        ref={ref}
        role="separator"
        aria-orientation={orientation}
        className={classes}
        style={mergedStyle}
        {...props}>
        {withText ? (
          <>
            <span className="divider-line" />
            <span className="divider-text">{children}</span>
            <span className="divider-line" />
          </>
        ) : null}
      </div>
    );
  },
);
