import { useState } from "react";
import type { ChartColor } from "./LineChart";

export interface FunnelDataPoint {
  label: string;
  value: number;
}

export interface FunnelChartProps {
  data: FunnelDataPoint[];
  /** SVG viewBox height in units. Default 300. */
  height?: number;
  /** Palette color used for the segments. Default "primary". */
  color?: ChartColor;
  /** Show the value centered in each segment. Default false. */
  showValues?: boolean;
  /** Show a hover tooltip. Default true. */
  showTooltip?: boolean;
  className?: string;
  ariaLabel?: string;
}

const PAD = { top: 16, right: 60, bottom: 16, left: 60 };
const VIEWBOX_WIDTH = 400;

export function FunnelChart({
  data,
  height = 300,
  color = "primary",
  showValues = false,
  showTooltip = true,
  className,
  ariaLabel = "Funnel chart",
}: FunnelChartProps) {
  const [hover, setHover] = useState<number | null>(null);

  if (!data || data.length === 0) return null;

  const n = data.length;
  const innerW = VIEWBOX_WIDTH - PAD.left - PAD.right;
  const innerH = height - PAD.top - PAD.bottom;
  const rowH = innerH / n;
  const maxValue = Math.max(...data.map((d) => d.value), 1);
  const cx = PAD.left + innerW / 2;

  const rows = data.map((d, i) => {
    const topW = (d.value / maxValue) * innerW;
    const bottomW =
      ((i === n - 1 ? d.value * 0.4 : data[i + 1].value) / maxValue) * innerW;
    const yTop = PAD.top + rowH * i;
    const yBottom = yTop + rowH;
    return {
      ...d,
      index: i,
      cx,
      yMid: yTop + rowH / 2,
      dPath: `M ${cx - topW / 2} ${yTop} L ${cx + topW / 2} ${yTop} L ${cx + bottomW / 2} ${yBottom} L ${cx - bottomW / 2} ${yBottom} Z`,
    };
  });

  const hovered = hover !== null ? data[hover] : null;

  return (
    <div
      className={["chart", `chart-${color}`, className]
        .filter(Boolean)
        .join(" ")}>
      <svg
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${height}`}
        role="img"
        aria-label={ariaLabel}>
        <title>{ariaLabel}</title>
        <g className="chart-funnels">
          {rows.map((row) => (
            <path
              key={`${row.label}-${row.index}`}
              className="chart-funnel"
              d={row.dPath}
              style={{
                fillOpacity:
                  hover === row.index ? 1 : 0.4 + (row.index / n) * 0.6,
              }}
              onMouseEnter={() => setHover(row.index)}
              onMouseLeave={() => setHover(null)}
            />
          ))}
        </g>
        {showValues &&
          rows.map((row) => (
            <text
              key={`v-${row.label}-${row.index}`}
              className="chart-funnel-value"
              x={row.cx}
              y={row.yMid + 4}
              textAnchor="middle">
              {row.value}
            </text>
          ))}
      </svg>
      {showTooltip && hovered && (
        <div
          className="chart-tooltip"
          style={{ left: "50%", top: `${((hover ?? 0) / n) * 100 + 5}%` }}>
          <span className="chart-tooltip-label">{hovered.label}</span>
          <span className="chart-tooltip-value">{hovered.value}</span>
        </div>
      )}
    </div>
  );
}
