import React from "react";
import "./Avatar.css";

export type AvatarSize = "sm" | "md" | "lg";
export type AvatarVariant = "square" | "rounded";
export type AvatarColor =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "danger"
  | "dark"
  | "light";

export interface UseAvatarProps {
  size?: AvatarSize;
  text?: string;
  image?: string;
  alt?: string;
  variant?: AvatarVariant;
  color?: AvatarColor;
}

export function useAvatar({
  size = "md",
  text,
  image,
  alt,
  variant = "rounded",
  color = "secondary",
}: UseAvatarProps) {
  const sizeMap = { sm: 32, md: 48, lg: 72 };
  const getInitials = (str?: string) => {
    if (!str) return "";
    const words = str.trim().split(/\s+/);
    if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
    return words
      .map((w) => w[0])
      .join("")
      .toUpperCase();
  };
  const dimension = sizeMap[size] || sizeMap.md;
  const borderRadius = variant === "square" ? "8px" : "50%";
  const colorClass = image ? "" : `avatar-${color}`;
  const ariaLabel = alt || text || "avatar";
  return {
    image,
    initials: getInitials(text),
    dimension,
    borderRadius,
    colorClass,
    ariaLabel,
    size,
    variant,
    color,
  };
}

export interface AvatarProps extends UseAvatarProps {
  /**
   * Optional custom render function for headless usage.
   * Receives all avatar logic and props.
   */
  render?: (avatar: ReturnType<typeof useAvatar>) => React.ReactNode;
  /**
   * Optional additional className for the root div.
   */
  className?: string;
  /**
   * Optional additional style for the root div.
   */
  style?: React.CSSProperties;
  /**
   * If true, avatar is decorative and hidden from assistive tech.
   */
  "aria-hidden"?: boolean;
  /**
   * Show a status dot (green by default) overlaid on the avatar.
   */
  status?: boolean;
  /**
   * Custom color for the status dot.
   */
  statusColor?: string;
}

const Avatar: React.FC<AvatarProps> = (props) => {
  const {
    render,
    className = "",
    style = {},
    "aria-hidden": ariaHidden,
    status,
    statusColor,
    ...avatarProps
  } = props;
  const avatar = useAvatar(avatarProps);
  if (render) {
    // Headless usage: user controls rendering
    return <>{render(avatar)}</>;
  }
  // Built-in UI usage
  const rootClass = [
    "avatar",
    `avatar-${avatar.size}`,
    `avatar-${avatar.variant}`,
    !avatar.image && avatar.colorClass ? avatar.colorClass : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");
  return (
    <div
      className={rootClass}
      style={{
        width: avatar.dimension,
        height: avatar.dimension,
        // Only set fallback background if no color class is present
        background:
          !avatar.image && !avatar.colorClass
            ? "var(--naytak-surface-2, linear-gradient(135deg, #e0e7ff 0%, #f1f5f9 100%))"
            : undefined,
        ...style,
      }}
      role={avatar.image ? undefined : "img"}
      aria-label={avatar.image ? undefined : avatar.ariaLabel}
      aria-hidden={ariaHidden}
      tabIndex={0}>
      {avatar.image ? (
        <img
          src={avatar.image}
          alt={avatar.ariaLabel}
          className="avatar-img"
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            borderRadius: avatar.borderRadius,
            transition: "opacity 0.3s cubic-bezier(.4,0,.2,1)",
          }}
        />
      ) : (
        <span className="avatar-text">{avatar.initials}</span>
      )}
      {/* Status dot (optional, overlays both image and text avatars) */}
      {status && (
        <span
          className="avatar-status-dot"
          style={{
            position: "absolute",
            bottom: 2,
            right: 2,
            width: 12,
            height: 12,
            borderRadius: "50%",
            background: statusColor || "#22c55e",
            border: "2px solid var(--naytak-surface, #fff)",
            boxShadow: "0 0 0 2px var(--naytak-surface, #f1f5f9)",
            pointerEvents: "none",
          }}
        />
      )}
    </div>
  );
};

export default Avatar;
