import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import "./ThemeProvider.css";
import {
  darkTokens,
  getPrimaryTokens,
  lightTokens,
  type ThemeContextValue,
  type ThemeMode,
  type ThemeTokens,
} from "./theme";

export interface ThemeProviderProps {
  children: ReactNode;
  /** Controlled color mode. Omit to use `defaultMode` (uncontrolled). */
  mode?: ThemeMode;
  /** Initial mode when `mode` is not provided. Default `"light"`. */
  defaultMode?: ThemeMode;
  /** Brand color used to derive component gradients. Default `"#2563eb"`. */
  primaryColor?: string;
  /** Extra CSS custom properties (full names like `"--my-token": "#fff"`). */
  tokens?: ThemeTokens;
  /** Fired on every mode change (both controlled and uncontrolled). */
  onModeChange?: (mode: ThemeMode) => void;
  /**
   * Also sync tokens + `data-naytak-theme` onto `<html>` so portal-rendered
   * components (Modal, Drawer, Toast) stay themed. Default `true`.
   */
  syncRoot?: boolean;
  /** Wrapper element used to scope the theme. Default `"div"`. */
  as?: React.ElementType;
  className?: string;
  style?: CSSProperties;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

/**
 * Provides a light/dark theme plus design tokens to every descendant
 * naytak-react-ui component.
 *
 * - Applies `--naytak-*` CSS custom properties on the wrapper (and syncs them
 *   to `<html>` so portals like Modal / Drawer / Toast are themed too).
 * - Sets `data-naytak-theme="light" | "dark"` for CSS targeting.
 * - Derives primary button gradients from `primaryColor`.
 */
export function ThemeProvider({
  children,
  mode: controlledMode,
  defaultMode = "light",
  primaryColor = "#2563eb",
  tokens: extraTokens,
  onModeChange,
  syncRoot = true,
  as: Component = "div",
  className,
  style,
}: ThemeProviderProps) {
  const [internalMode, setInternalMode] = useState<ThemeMode>(defaultMode);
  const mode = controlledMode ?? internalMode;

  const setMode = useCallback(
    (next: ThemeMode) => {
      onModeChange?.(next);
      if (controlledMode === undefined) setInternalMode(next);
    },
    [controlledMode, onModeChange],
  );
  const toggleMode = useCallback(
    () => setMode(mode === "dark" ? "light" : "dark"),
    [mode, setMode],
  );

  const tokens = useMemo<ThemeTokens>(() => {
    const modeTokens = mode === "dark" ? darkTokens : lightTokens;
    return {
      ...lightTokens,
      ...modeTokens,
      ...getPrimaryTokens(primaryColor),
      ...extraTokens,
    };
  }, [mode, primaryColor, extraTokens]);

  // Sync tokens + data-theme onto <html> so portal-rendered components
  // (Modal, Drawer, DropdownMenu, Toast) pick up the theme as well.
  useLayoutEffect(() => {
    if (!syncRoot) return;
    const root = document.documentElement;
    root.setAttribute("data-naytak-theme", mode);
    const previous: Record<string, string | null> = {};
    for (const [key, value] of Object.entries(tokens)) {
      previous[key] = root.style.getPropertyValue(key) || null;
      root.style.setProperty(key, value);
    }
    return () => {
      for (const [key, value] of Object.entries(previous)) {
        if (value === null) root.style.removeProperty(key);
        else root.style.setProperty(key, value);
      }
      root.removeAttribute("data-naytak-theme");
    };
  }, [mode, tokens, syncRoot]);

  const contextValue = useMemo<ThemeContextValue>(
    () => ({ mode, setMode, toggleMode, primaryColor, tokens }),
    [mode, setMode, toggleMode, primaryColor, tokens],
  );

  return (
    <ThemeContext.Provider value={contextValue}>
      <Component
        className={["naytak-theme", className].filter(Boolean).join(" ")}
        data-naytak-theme={mode}
        style={{ ...tokens, ...style }}>
        {children}
      </Component>
    </ThemeContext.Provider>
  );
}

/** Access the current theme from anywhere under a `ThemeProvider`. */
// eslint-disable-next-line react-refresh/only-export-components
export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (!ctx) {
    throw new Error("useTheme must be used within a <ThemeProvider>");
  }
  return ctx;
}
