import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import {
  removeToast,
  subscribeToasts,
  toast,
  type ToastItem,
  type ToastPosition,
  type ToastState,
  type ToastType,
} from "./toast";

export interface ToastProviderProps {
  children: ReactNode;
  position?: ToastPosition;
  /** Maximum number of toasts rendered at once. Default 5. */
  max?: number;
}

const ToastContext = createContext<ToastState>(toast);

export function ToastProvider({
  children,
  position = "top-right",
  max = 5,
}: ToastProviderProps) {
  const [items, setItems] = useState<ToastItem[]>([]);

  useEffect(() => subscribeToasts((t) => setItems(t.slice(-max))), [max]);

  return (
    <ToastContext.Provider value={toast}>
      {children}
      <div
        className={["toast-manager", `toast-manager-${position}`].join(" ")}
        role="region"
        aria-label="Notifications">
        {items.map((t) => (
          <ToastCard key={t.id} item={t} onDismiss={() => removeToast(t.id)} />
        ))}
      </div>
    </ToastContext.Provider>
  );
}

// eslint-disable-next-line react-refresh/only-export-components
export function useToast(): ToastState {
  return useContext(ToastContext);
}

function ToastCard({
  item,
  onDismiss,
}: {
  item: ToastItem;
  onDismiss: () => void;
}) {
  return (
    <div
      className={`toast-manager-card toast-manager-${item.type}`}
      role="status">
      <span className="toast-manager-icon" aria-hidden="true">
        {ICONS[item.type]}
      </span>
      <div className="toast-manager-content">
        {item.title && <div className="toast-manager-title">{item.title}</div>}
        <div className="toast-manager-message">{item.message}</div>
      </div>
      <button
        type="button"
        className="toast-manager-close"
        aria-label="Dismiss notification"
        onClick={onDismiss}>
        ×
      </button>
    </div>
  );
}

