import { useState } from "react";
import { polarToCartesian } from "./chartUtils";
import type { ChartColor } from "./LineChart";

export interface PieDataPoint {
  label: string;
  value: number;
  /** Optional per-slice color: a palette key (ChartColor) or any CSS color string. */
  color?: ChartColor | string;
}

export interface PieChartProps {
  data: PieDataPoint[];
  /** Square viewBox size in units. Default 300. */
  size?: number;
  /** Inner radius as a ratio of the outer radius (0 = pie, 0.5+ = donut). Default 0. */
  innerRadius?: number;
  /** Show percentage labels on the slices. Default false. */
  showLabels?: boolean;
  /** Show a legend below the chart. Default true. */
  showLegend?: boolean;
  /** Color of the stroke separating slices. Default "#fff". */
  stroke?: string;
  /** Show a hover tooltip. Default true. */
  showTooltip?: boolean;
  className?: string;
  ariaLabel?: string;
}

const PALETTE: ChartColor[] = [
  "primary",
  "secondary",
  "success",
  "warning",
  "danger",
  "info",
  "dark",
  "light",
];

function isPaletteColor(c: string | undefined): c is ChartColor {
  return c !== undefined && (PALETTE as string[]).includes(c);
}

const PAD = 16;
const LABEL_RADIUS_RATIO = 0.62;

export function PieChart({
  data,
  size = 300,
  innerRadius = 0,
  showLabels = false,
  showLegend = true,
  stroke = "#fff",
  showTooltip = true,
  className,
  ariaLabel = "Pie chart",
}: PieChartProps) {
  const [hover, setHover] = useState<number | null>(null);

  if (!data || data.length === 0) return null;

  const total = data.reduce((sum, d) => sum + d.value, 0);
  if (total <= 0) return null;

  const cx = size / 2;
  const cy = size / 2;
  const outerR = size / 2 - PAD;
  const innerR = outerR * Math.min(Math.max(innerRadius, 0), 0.9);
  const single = data.length === 1;

  let cursor = 0;
  const slices = data.map((d, i) => {
    const sweep = (d.value / total) * 360;
    const slice = {
      ...d,
      index: i,
      startAngle: cursor,
      endAngle: cursor + sweep,
      sweep,
    };
    cursor += sweep;
    return slice;
  });

  const slicePath = (s: (typeof slices)[number]) => {
    const largeArc = s.sweep > 180 ? 1 : 0;
    const oStart = polarToCartesian(cx, cy, outerR, s.startAngle);
    const oEnd = polarToCartesian(cx, cy, outerR, s.endAngle);
    if (innerR <= 0) {
      return `M ${cx} ${cy} L ${oStart.x} ${oStart.y} A ${outerR} ${outerR} 0 ${largeArc} 1 ${oEnd.x} ${oEnd.y} Z`;
    }
    const iEnd = polarToCartesian(cx, cy, innerR, s.endAngle);
    const iStart = polarToCartesian(cx, cy, innerR, s.startAngle);
    return `M ${oStart.x} ${oStart.y} A ${outerR} ${outerR} 0 ${largeArc} 1 ${oEnd.x} ${oEnd.y} L ${iEnd.x} ${iEnd.y} A ${innerR} ${innerR} 0 ${largeArc} 0 ${iStart.x} ${iStart.y} Z`;
  };

  const fullCircle = (r: number, reverse = false) => {
    const dir = reverse ? "0" : "1";
    return `M ${cx} ${cy} m -${r},0 a ${r},${r} 0 1,${dir} ${2 * r},0 a ${r},${r} 0 1,${dir} -${2 * r},0`;
  };

  const labelAt = (s: (typeof slices)[number]) => {
    const mid = s.startAngle + s.sweep / 2;
    const r = innerR > 0 ? (outerR + innerR) / 2 : outerR * LABEL_RADIUS_RATIO;
    return polarToCartesian(cx, cy, r, mid);
  };

  const hovered = hover !== null ? data[hover] : null;

  return (
    <div className={["chart", className].filter(Boolean).join(" ")}>
      <svg viewBox={`0 0 ${size} ${size}`} role="img" aria-label={ariaLabel}>
        <title>{ariaLabel}</title>
        {single ? (
          <path
            className={[
              "chart-slice",
              isPaletteColor(data[0].color)
                ? `chart-${data[0].color}`
                : "chart-primary",
            ]
              .filter(Boolean)
              .join(" ")}
            style={
              data[0].color && !isPaletteColor(data[0].color)
                ? { fill: data[0].color }
                : undefined
            }
            d={
              innerR > 0
                ? `${fullCircle(outerR)} ${fullCircle(innerR, true)}`
                : fullCircle(outerR)
            }
            fillRule={innerR > 0 ? "evenodd" : undefined}
            stroke={stroke}
          />
        ) : (
          slices.map((s) => (
            <path
              key={`${s.label}-${s.index}`}
              className={[
                "chart-slice",
                isPaletteColor(s.color)
                  ? `chart-${s.color}`
                  : `chart-${PALETTE[s.index % PALETTE.length]}`,
                hover === s.index ? "chart-slice-hover" : "",
              ]
                .filter(Boolean)
                .join(" ")}
              style={
                s.color && !isPaletteColor(s.color)
                  ? { fill: s.color }
                  : undefined
              }
              d={slicePath(s)}
              stroke={stroke}
              onMouseEnter={() => setHover(s.index)}
              onMouseLeave={() => setHover(null)}
            />
          ))
        )}
        {!single &&
          showLabels &&
          slices.map((s) => {
            const p = labelAt(s);
            return (
              <text
                key={`l-${s.label}-${s.index}`}
                className="chart-slice-label"
                x={p.x}
                y={p.y + 4}
                textAnchor="middle">
                {Math.round((s.value / total) * 100)}%
              </text>
            );
          })}
      </svg>
      {showLegend && (
        <div className="chart-legend" role="list">
          {data.map((d, i) => (
            <span
              key={`${d.label}-${i}`}
              className="chart-legend-item"
              role="listitem">
              <span
                className={[
                  "chart-legend-swatch",
                  isPaletteColor(d.color)
                    ? `chart-${d.color}`
                    : `chart-${PALETTE[i % PALETTE.length]}`,
                ]
                  .filter(Boolean)
                  .join(" ")}
                style={
                  d.color && !isPaletteColor(d.color)
                    ? { background: d.color }
                    : undefined
                }
              />
              {d.label}
            </span>
          ))}
        </div>
      )}
      {showTooltip && hovered && (
        <div className="chart-tooltip" style={{ left: "50%", top: "42%" }}>
          <span className="chart-tooltip-label">{hovered.label}</span>
          <span className="chart-tooltip-value">
            {hovered.value} ({Math.round((hovered.value / total) * 100)}%)
          </span>
        </div>
      )}
    </div>
  );
}
