import type { ReactNode } from "react";

export type TimelineColor =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "danger"
  | "info"
  | "dark"
  | "light";

export interface TimelineItem {
  title: string;
  time?: string;
  content?: ReactNode;
  icon?: ReactNode;
  color?: TimelineColor;
}

export interface TimelineProps {
  items: TimelineItem[];
  orientation?: "vertical" | "horizontal";
  size?: "sm" | "md" | "lg";
  className?: string;
}

export function Timeline({
  items,
  orientation = "vertical",
  size = "md",
  className,
}: TimelineProps) {
  return (
    <div
      className={[
        "timeline",
        `timeline-${orientation}`,
        `timeline-${size}`,
        className,
      ]
        .filter(Boolean)
        .join(" ")}>
      {items.map((item, i) => (
        <div className="timeline-item" key={`${item.title}-${i}`}>
          <span
            className={[
              "timeline-dot",
              `timeline-${item.color ?? "primary"}`,
            ].join(" ")}>
            {item.icon}
          </span>
          <div className="timeline-content">
            <div className="timeline-title">{item.title}</div>
            {item.time && <div className="timeline-time">{item.time}</div>}
            {item.content !== undefined && (
              <div className="timeline-body">{item.content}</div>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
