export type ThemeMode = "light" | "dark";

export interface ThemeTokens {
  [token: string]: string;
}

export interface ThemeContextValue {
  /** Current color mode. */
  mode: ThemeMode;
  /** Switch to a specific mode. */
  setMode: (mode: ThemeMode) => void;
  /** Flip between light and dark. */
  toggleMode: () => void;
  /** Active brand color (the `primaryColor` prop). */
  primaryColor: string;
  /** Fully resolved design tokens applied to the DOM. */
  tokens: ThemeTokens;
}

/* ---------- Color helpers ---------- */

/** Parse `#rgb` / `#rrggbb` into an RGB object. Falls back to a safe blue. */
export function hexToRgb(hex: string): { r: number; g: number; b: number } {
  let value = hex.trim().replace(/^#/, "");
  if (value.length === 3) {
    value = value
      .split("")
      .map((c) => c + c)
      .join("");
  }
  if (!/^[0-9a-f]{6}$/i.test(value)) {
    return { r: 37, g: 99, b: 235 };
  }
  const num = parseInt(value, 16);
  return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255 };
}

/** Render a color as a modern `rgb(r g b / a)` string. */
export function rgba(hex: string, alpha: number): string {
  const { r, g, b } = hexToRgb(hex);
  return `rgb(${r} ${g} ${b} / ${alpha})`;
}

function mix(hex: string, target: string, weight: number): string {
  const a = hexToRgb(hex);
  const b = hexToRgb(target);
  const w = Math.min(1, Math.max(0, weight));
  const channel = (ca: number, cb: number) => Math.round(ca + (cb - ca) * w);
  const toHex = (n: number) => n.toString(16).padStart(2, "0");
  return `#${toHex(channel(a.r, b.r))}${toHex(channel(a.g, b.g))}${toHex(
    channel(a.b, b.b),
  )}`;
}

/** Lighten (positive) or darken (negative) a hex color by `amount` (0..1). */
export function shade(hex: string, amount: number): string {
  return mix(hex, amount >= 0 ? "#ffffff" : "#000000", Math.abs(amount));
}

/* ---------- Token builders ---------- */

/** Brand tokens derived from the primary color (mirrors the button gradient). */
export function getPrimaryTokens(primary: string): ThemeTokens {
  return {
    "--naytak-primary": primary,
    "--naytak-primary-light": shade(primary, 0.18),
    "--naytak-primary-dark": shade(primary, -0.16),
    "--naytak-primary-darker": shade(primary, -0.3),
    "--naytak-primary-soft": rgba(primary, 0.12),
    "--naytak-primary-soft-strong": rgba(primary, 0.18),
    "--naytak-primary-focus": rgba(primary, 0.15),
    "--naytak-primary-glow": `0 8px 22px -6px ${rgba(primary, 0.55)}`,
    "--naytak-primary-contrast": "#ffffff",
  };
}

