import {
  forwardRef,
  useId,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import "./Drawer.css";

export type DrawerPlacement = "top" | "right" | "bottom" | "left";
export type DrawerSize = "sm" | "md" | "lg";

export interface DrawerProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "title"
> {
  open: boolean;
  onClose?: () => void;
  placement?: DrawerPlacement;
  size?: DrawerSize;
  title?: ReactNode;
  footer?: ReactNode;
  closeOnOverlayClick?: boolean;
  closeOnEscape?: boolean;
  showCloseButton?: boolean;
  transitionDuration?: number;
  className?: string;
  children?: ReactNode;
}

const sizeClass = (placement: DrawerPlacement, size: DrawerSize) => {
  const axis = placement === "top" || placement === "bottom" ? "h" : "w";
  return `drawer-${axis}-${size}`;
};

export const Drawer = forwardRef<HTMLDivElement, DrawerProps>(function Drawer(
  {
    open,
    onClose,
    placement = "right",
    size = "md",
    title,
    footer,
    closeOnOverlayClick = true,
    closeOnEscape = true,
    showCloseButton = true,
    transitionDuration = 250,
    className,
    children,
    ...props
  },
  ref,
) {
  const titleId = useId();
  const [rendered, setRendered] = useState<boolean>(open);
  const [exiting, setExiting] = useState<boolean>(false);
  const exitTimer = useRef<number | null>(null);
  const [entering, setEntering] = useState<boolean>(false);

  useEffect(() => {
    if (!open || !closeOnEscape) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose?.();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, closeOnEscape, onClose]);

  // Mount/unmount with exit animation support
  useEffect(() => {
    if (open) {
      setRendered(true);
      setExiting(false);
      setEntering(true);
      // Double rAF: the first fires before the browser paints, so a single
      // rAF would remove `is-entering` before the hidden state was ever drawn
      // and no CSS transition would run. A second rAF guarantees the browser
      // paints the initial hidden state, then animates to visible.
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setEntering(false);
        });
      });
      if (exitTimer.current) {
        window.clearTimeout(exitTimer.current);
        exitTimer.current = null;
      }
    } else if (rendered) {
      setExiting(true);
      if (exitTimer.current) window.clearTimeout(exitTimer.current);
      exitTimer.current = window.setTimeout(() => {
        setRendered(false);
        setExiting(false);
        exitTimer.current = null;
      }, transitionDuration);
    }
    return () => {
      if (exitTimer.current) {
        window.clearTimeout(exitTimer.current);
        exitTimer.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, transitionDuration]);

  if (!rendered) return null;

  const rootCls = [
    "drawer",
    `drawer-${placement}`,
    sizeClass(placement, size),
    exiting ? "is-exiting" : entering ? "is-entering" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const handleOverlayClick = () => {
    if (closeOnOverlayClick) onClose?.();
  };
  const stop = (e: MouseEvent) => e.stopPropagation();

  const header =
    title || (showCloseButton && onClose) ? (
      <div className="drawer-header">
        {title ? (
          <div className="drawer-title" id={titleId}>
            {title}
          </div>
        ) : (
          <span />
        )}
        {showCloseButton && onClose ? (
          <button
            type="button"
            className="drawer-close"
            aria-label="Close drawer"
            onClick={onClose}>
            ×
          </button>
        ) : null}
      </div>
    ) : null;

  return createPortal(
    <div
      ref={ref}
      role="dialog"
      aria-modal="true"
      aria-labelledby={title ? titleId : undefined}
      data-state={exiting ? "exit" : "enter"}
      className={rootCls}
      style={
        { "--ui-drawer-duration": `${transitionDuration}ms` } as CSSProperties
      }
      {...props}>
      <div className="drawer-overlay" onClick={handleOverlayClick}>
        <aside className="drawer-panel" onClick={stop}>
          {header}
          <div className="drawer-body">{children}</div>
          {footer ? <div className="drawer-footer">{footer}</div> : null}
        </aside>
      </div>
    </div>,
    document.body,
  );
});
