import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import "./DropdownMenu.css";

export interface DropdownItem {
  key: string;
  label: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
  danger?: boolean;
  shortcut?: string;
  onClick?: () => void;
  divider?: boolean;
}

export type DropdownAlign = "start" | "end";
export type DropdownPosition = "bottom" | "top";

export interface DropdownMenuProps extends HTMLAttributes<HTMLDivElement> {
  items: DropdownItem[];
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  align?: DropdownAlign;
  position?: DropdownPosition;
  closeOnSelect?: boolean;
  closeOnOutsideClick?: boolean;
  className?: string;
}

export const DropdownMenu = forwardRef<HTMLDivElement, DropdownMenuProps>(
  function DropdownMenu(
    {
      items,
      children,
      open,
      defaultOpen = false,
      onOpenChange,
      align = "start",
      position = "bottom",
      closeOnSelect = true,
      closeOnOutsideClick = true,
      className,
      ...props
    },
    ref,
  ) {
    const [internalOpen, setInternalOpen] = useState(defaultOpen);
    const isControlled = open !== undefined;
    const isOpen = isControlled ? open : internalOpen;

    const rootRef = useRef<HTMLDivElement | null>(null);
    const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);
    const focusedOnce = useRef(false);

    const setOpen = useCallback(
      (next: boolean) => {
        if (!isControlled) setInternalOpen(next);
        onOpenChange?.(next);
      },
      [isControlled, onOpenChange],
    );

    const combineRef = useCallback(
      (node: HTMLDivElement | null) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      },
      [ref],
    );

    const nextEnabled = (from: number, dir: 1 | -1) => {
      let i = from;
      for (let step = 0; step < items.length; step++) {
        i = (i + dir + items.length) % items.length;
        const item = items[i];
        if (item && !item.divider && !item.disabled) return i;
      }
      return -1;
    };

    const handleItemClick = (item: DropdownItem) => {
      if (item.disabled) return;
      item.onClick?.();
      if (closeOnSelect) setOpen(false);
    };

    const handleTriggerClick = () => {
      setOpen(!isOpen);
    };

    const handleMenuKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
      const currentIndex = itemRefs.current.findIndex(
        (el) => el === document.activeElement,
      );
      if (e.key === "ArrowDown") {
        e.preventDefault();
        const next = nextEnabled(currentIndex, 1);
        if (next >= 0) itemRefs.current[next]?.focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        const prev = nextEnabled(currentIndex, -1);
        if (prev >= 0) itemRefs.current[prev]?.focus();
      } else if (e.key === "Home") {
        e.preventDefault();
        const first = nextEnabled(-1, 1);
        if (first >= 0) itemRefs.current[first]?.focus();
      } else if (e.key === "End") {
        e.preventDefault();
        const last = nextEnabled(items.length, -1);
        if (last >= 0) itemRefs.current[last]?.focus();
      }
    };

    // Close on Escape / outside click while open
    useEffect(() => {
      if (!isOpen) return;
      const onPointerDown = (e: PointerEvent) => {
        if (!closeOnOutsideClick) return;
        if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
          setOpen(false);
        }
      };
      const onKeyDown = (e: globalThis.KeyboardEvent) => {
        if (e.key === "Escape") setOpen(false);
      };
      document.addEventListener("pointerdown", onPointerDown);
      document.addEventListener("keydown", onKeyDown);
      return () => {
        document.removeEventListener("pointerdown", onPointerDown);
        document.removeEventListener("keydown", onKeyDown);
      };
    }, [isOpen, setOpen, closeOnOutsideClick]);

    // Focus the first enabled item once when the menu opens
    useEffect(() => {
      if (isOpen) {
        if (!focusedOnce.current) {
          const first = items.findIndex(
            (item) => !item.divider && !item.disabled,
          );
          if (first >= 0) itemRefs.current[first]?.focus();
          focusedOnce.current = true;
        }
      } else {
        focusedOnce.current = false;
      }
    }, [isOpen, items]);

    return (
      <div
        ref={combineRef}
        className={["dropdown", className].filter(Boolean).join(" ")}
        {...props}>
        <div
          className="dropdown-trigger"
          aria-haspopup="menu"
          aria-expanded={isOpen}
          onClick={handleTriggerClick}>
          {children}
        </div>
        {isOpen ? (
          <div
            role="menu"
            className={[
              "dropdown-menu",
              `dropdown-align-${align}`,
              `dropdown-position-${position}`,
            ]
              .filter(Boolean)
              .join(" ")}
            onKeyDown={handleMenuKeyDown}>
            {items.map((item, index) =>
              item.divider ? (
                <div
                  key={item.key}
                  role="separator"
                  className="dropdown-divider"
                />
              ) : (
                <button
                  key={item.key}
                  ref={(node) => {
                    itemRefs.current[index] = node;
                  }}
                  type="button"
                  role="menuitem"
                  disabled={item.disabled}
                  className={[
                    "dropdown-item",
                    item.danger ? "dropdown-item-danger" : "",
                    item.disabled ? "dropdown-item-disabled" : "",
                  ]
                    .filter(Boolean)
                    .join(" ")}
                  onClick={() => handleItemClick(item)}>
                  {item.icon ? (
                    <span className="dropdown-item-icon">{item.icon}</span>
                  ) : null}
                  <span className="dropdown-item-label">{item.label}</span>
                  {item.shortcut ? (
                    <span className="dropdown-item-shortcut">
                      {item.shortcut}
                    </span>
                  ) : null}
                </button>
              ),
            )}
          </div>
        ) : null}
      </div>
    );
  },
);
