import React from "react";
import "./Badge.css";

export type BadgeColor =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "danger"
  | "dark"
  | "light"
  | "info";

export type BadgeVariant = "normal" | "pill" | "outline" | "dot";

export type BadgeSize = "sm" | "md" | "lg";

export interface BadgeProps {
  color?: BadgeColor;
  size?: BadgeSize;
  variant?: BadgeVariant;
  className?: string;
  children?: React.ReactNode;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  block?: boolean;
  removable?: boolean;
  onRemove?: () => void;
  as?: React.ElementType;
  render?: (props: ReturnType<typeof useBadge>) => React.ReactNode;
}

function useBadge({
  color = "secondary",
  size = "md",
  variant = "normal",
  className = "",
  block = false,
}: BadgeProps) {
  return {
    color,
    size,
    variant,
    className,
    block,
    classes: [
      "badge",
      `badge-${color}`,
      `badge-${size}`,
      `badge-${variant}`,
      block ? "badge-block" : "",
      className,
    ]
      .filter(Boolean)
      .join(" "),
  };
}

const Badge: React.FC<BadgeProps> = (props) => {
  const {
    children,
    leftIcon,
    rightIcon,
    removable,
    onRemove,
    as: Component = "span",
    render,
    ...badgeProps
  } = props;
  const badge = useBadge(badgeProps);
  if (render) {
    return <>{render(badge)}</>;
  }
  if (badge.variant === "dot") {
    return (
      <Component
        className={badge.classes + " badge-dot"}
        aria-label={typeof children === "string" ? children : undefined}
      />
    );
  }
  return (
    <Component className={badge.classes} tabIndex={0}>
      {leftIcon && (
        <span className="badge-icon badge-icon-left">{leftIcon}</span>
      )}
      {children}
      {rightIcon && (
        <span className="badge-icon badge-icon-right">{rightIcon}</span>
      )}
      {removable && (
        <button
          type="button"
          className="badge-remove"
          aria-label="Remove badge"
          tabIndex={0}
          onClick={onRemove}>
          ×
        </button>
      )}
    </Component>
  );
};

export default Badge;
