import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import "./EmptyState.css";

export type EmptyStateSize = "sm" | "md" | "lg";

export interface EmptyStateProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "title"
> {
  title?: ReactNode;
  description?: ReactNode;
  icon?: ReactNode;
  action?: ReactNode;
  size?: EmptyStateSize;
  className?: string;
}

const DefaultIcon = () => (
  <svg
    width="40"
    height="40"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.5"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true">
    <path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z" />
    <path d="m3.3 7 8.7 5 8.7-5" />
    <path d="M12 22V12" />
  </svg>
);

export const EmptyState = forwardRef<HTMLDivElement, EmptyStateProps>(
  function EmptyState(
    { title, description, icon, action, size = "md", className, ...props },
    ref,
  ) {
    return (
      <div
        ref={ref}
        className={["empty-state", `empty-state-${size}`, className]
          .filter(Boolean)
          .join(" ")}
        {...props}>
        <div className="empty-state-icon">{icon ?? <DefaultIcon />}</div>
        {title ? <h3 className="empty-state-title">{title}</h3> : null}
        {description ? (
          <p className="empty-state-description">{description}</p>
        ) : null}
        {action ? <div className="empty-state-action">{action}</div> : null}
      </div>
    );
  },
);
