import { useRef, useState, type MouseEvent as ReactMouseEvent } from "react";
import { linearScale, niceTicks } from "./scales";
import { polylinePath, smoothPath, type Point } from "./chartUtils";
import { ChartLegend } from "./ChartLegend";
import type { ChartColor, ChartSeries } from "./LineChart";

export interface AreaChartProps {
  /** Multi-series data; areas are stacked cumulatively. */
  series: ChartSeries[];
  /** SVG viewBox height in units. Default 300. */
  height?: number;
  /** Show horizontal grid lines. Default true. */
  showGrid?: boolean;
  /** Show x/y axis labels. Default true. */
  showAxes?: boolean;
  /** Show a legend below the chart. Default true. */
  showLegend?: boolean;
  /** Show a hover tooltip. Default true. */
  showTooltip?: boolean;
  /** Smooth the area top edges with cubic Bézier segments. Default true. */
  curve?: boolean;
  className?: string;
  ariaLabel?: string;
}

const PAD = { top: 16, right: 16, bottom: 30, left: 44 };
const VIEWBOX_WIDTH = 600;
const PALETTE: ChartColor[] = [
  "primary",
  "secondary",
  "success",
  "warning",
  "danger",
  "info",
  "dark",
  "light",
];

export function AreaChart({
  series,
  height = 300,
  showGrid = true,
  showAxes = true,
  showLegend = true,
  showTooltip = true,
  curve = true,
  className,
  ariaLabel = "Area chart",
}: AreaChartProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [hover, setHover] = useState<number | null>(null);

  if (!series || series.length === 0 || !series[0]?.data.length) return null;

  const count = series[0].data.length;
  const innerW = VIEWBOX_WIDTH - PAD.left - PAD.right;
  const innerH = height - PAD.top - PAD.bottom;
  const baseline = PAD.top + innerH;

  const totals: number[] = [];
  for (let i = 0; i < count; i++) {
    totals.push(series.reduce((s, sr) => s + (sr.data[i]?.y ?? 0), 0));
  }
  const domainMax = Math.max(...totals, 0) * 1.1 || 1;
  const yScale = linearScale([0, domainMax], [innerH, 0]);
  const xAt = (i: number) =>
    PAD.left + (count > 1 ? (i / (count - 1)) * innerW : innerW / 2);

  const rendered = series.map((sr, si) => {
    const tops: Point[] = [];
    const bottoms: Point[] = [];
    let cumulative = 0;
    for (let i = 0; i < count; i++) {
      const x = xAt(i);
      const y = sr.data[i]?.y ?? 0;
      tops.push({ x, y: PAD.top + yScale(cumulative + y) });
      bottoms.push({ x, y: PAD.top + yScale(cumulative) });
      cumulative += y;
    }
    const topPath = curve ? smoothPath(tops) : polylinePath(tops);
    const last = bottoms[bottoms.length - 1];
    const areaPath = `${topPath} L ${last.x} ${last.y} ${bottoms
      .slice(0, -1)
      .reverse()
      .map((p) => ` L ${p.x} ${p.y}`)
      .join("")} Z`;
    return {
      ...sr,
      color: sr.color ?? PALETTE[si % PALETTE.length],
      topPath,
      areaPath,
    };
  });

  const ticks = niceTicks(0, domainMax, 5);

  const handleMove = (e: ReactMouseEvent<SVGSVGElement>) => {
    if (!showTooltip) return;
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return;
    const localX = ((e.clientX - rect.left) / rect.width) * VIEWBOX_WIDTH;
    let nearest = 0;
    let best = Infinity;
    for (let i = 0; i < count; i++) {
      const dist = Math.abs(xAt(i) - localX);
      if (dist < best) {
        best = dist;
        nearest = i;
      }
    }
    setHover(nearest);
  };

  const hoveredX = hover !== null ? xAt(hover) : 0;

  return (
    <div className={["chart", className].filter(Boolean).join(" ")}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${height}`}
        role="img"
        aria-label={ariaLabel}
        onMouseMove={handleMove}
        onMouseLeave={() => setHover(null)}>
        <title>{ariaLabel}</title>
        {showGrid && (
          <g className="chart-grid">
            {ticks.map((t) => (
              <line
                key={t}
                x1={PAD.left}
                x2={VIEWBOX_WIDTH - PAD.right}
                y1={yScale(t)}
                y2={yScale(t)}
              />
            ))}
          </g>
        )}
        {rendered.map((r) => (
          <g key={r.name} className={`chart-series chart-${r.color}`}>
            <path className="chart-area-series" d={r.areaPath} />
            <path className="chart-area-line" d={r.topPath} />
          </g>
        ))}
        {showAxes && (
          <g className="chart-axis">
            {ticks.map((t) => (
              <text key={t} x={PAD.left - 8} y={yScale(t) + 4} textAnchor="end">
                {t}
              </text>
            ))}
            {series[0].data.map((d, i) => (
              <text
                key={`${d.x}-${i}`}
                x={xAt(i)}
                y={height - 8}
                textAnchor="middle">
                {d.x}
              </text>
            ))}
          </g>
        )}
        {showTooltip && hover !== null && (
          <line
            className="chart-hover-line"
            x1={hoveredX}
            x2={hoveredX}
            y1={PAD.top}
            y2={baseline}
          />
        )}
      </svg>
      {showLegend && (
        <ChartLegend
          series={rendered.map((r) => ({ name: r.name, color: r.color }))}
        />
      )}
      {showTooltip && hover !== null && (
        <div
          className="chart-tooltip"
          style={{ left: `${(hoveredX / VIEWBOX_WIDTH) * 100}%`, top: "10%" }}>
          <span className="chart-tooltip-label">
            {String(series[0].data[hover].x)}
          </span>
          <div className="chart-tooltip-rows">
            {rendered.map((r) => (
              <div key={r.name} className="chart-tooltip-row">
                <span className={`chart-legend-swatch chart-${r.color}`} />
                {r.name}: {r.data[hover]?.y ?? 0}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
