import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type InputHTMLAttributes,
  type ReactNode,
} from "react";
import "./SearchInput.css";

const DEFAULT_ICON = (
  <svg
    width="16"
    height="16"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true">
    <circle cx="11" cy="11" r="8" />
    <path d="m21 21-4.3-4.3" />
  </svg>
);

export interface SearchInputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "onChange"
> {
  label?: string;
  /** Delay (ms) before `onChange`/`onSearch` fire after typing. Default 0. */
  debounce?: number;
  /** Controlled value. */
  value?: string;
  /** Uncontrolled initial value. */
  defaultValue?: string;
  /** Fired (after debounce) on every value change. */
  onChange?: (value: string) => void;
  /** Fired (after debounce) on every value change — alias for search UIs. */
  onSearch?: (value: string) => void;
  /** Fired immediately when the clear button is pressed. */
  onClear?: () => void;
  /** Show a clear (×) button when there is a value. */
  clearable?: boolean;
  /** Show a loading spinner on the right instead of the clear button. */
  loading?: boolean;
  /** Custom leading icon. */
  icon?: ReactNode;
}

/**
 * A search text input with a leading icon, optional debounce, and an optional
 * clear button. Controlled + uncontrolled; theme-aware.
 */
export const SearchInput = forwardRef<HTMLInputElement, SearchInputProps>(
  function SearchInput(
    {
      label,
      debounce = 0,
      value: controlledValue,
      defaultValue = "",
      onChange,
      onSearch,
      onClear,
      clearable = true,
      loading = false,
      icon = DEFAULT_ICON,
      className,
      placeholder = "Search…",
      id,
      disabled,
      ...props
    },
    ref,
  ) {
    const autoId = useId();
    const inputId = id ?? `search-${autoId}`;
    const isControlled = controlledValue !== undefined;
    const [internal, setInternal] = useState(defaultValue);
    const value = isControlled ? controlledValue : internal;
    const inputRef = useRef<HTMLInputElement | null>(null);

    const notify = (next: string) => {
      onChange?.(next);
      onSearch?.(next);
    };

    useEffect(() => {
      if (debounce <= 0) return;
      const timer = window.setTimeout(() => notify(value), debounce);
      return () => window.clearTimeout(timer);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [value, debounce]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const next = e.target.value;
      if (!isControlled) setInternal(next);
      if (debounce <= 0) notify(next);
    };

    const handleClear = () => {
      if (!isControlled) setInternal("");
      notify("");
      onClear?.();
      inputRef.current?.focus();
    };

    const showClear = !loading && clearable && value.length > 0;

    return (
      <div className={["search-input", className].filter(Boolean).join(" ")}>
        {label ? (
          <label className="search-input-label" htmlFor={inputId}>
            {label}
          </label>
        ) : null}
        <div className="search-input-control">
          <span className="search-input-icon">{icon}</span>
          <input
            ref={(node) => {
              inputRef.current = node;
              if (typeof ref === "function") ref(node);
              else if (ref) ref.current = node;
            }}
            id={inputId}
            type="search"
            className="search-input-field"
            value={value}
            placeholder={placeholder}
            disabled={disabled}
            onChange={handleChange}
            {...props}
          />
          {loading ? (
            <span className="search-input-spinner" aria-hidden="true" />
          ) : showClear ? (
            <button
              type="button"
              className="search-input-action"
              aria-label="Clear search"
              onClick={handleClear}>
              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true">
                <path d="M18 6 6 18" />
                <path d="m6 6 12 12" />
              </svg>
            </button>
          ) : null}
        </div>
      </div>
    );
  },
);
