import { useRef, useState, type MouseEvent as ReactMouseEvent } from "react";
import { linearScale, niceTicks } from "./scales";
import { polylinePath, smoothPath, type Point } from "./chartUtils";

export type ChartColor =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "danger"
  | "info"
  | "dark"
  | "light";

export interface ChartDataPoint {
  x: string | number;
  y: number;
}

/** A named data series used by multi-series charts (Area, Grouped/Stacked Bar). */
export interface ChartSeries {
  name: string;
  color?: ChartColor;
  data: ChartDataPoint[];
}

export interface LineChartProps {
  data: ChartDataPoint[];
  /** SVG viewBox height in units. Default 300. */
  height?: number;
  /** Palette color used for the line / fill / points. Default "primary". */
  color?: ChartColor;
  /** Show horizontal grid lines. Default true. */
  showGrid?: boolean;
  /** Show x/y axis labels. Default true. */
  showAxes?: boolean;
  /** Show a dot at every data point. Default false. */
  showPoints?: boolean;
  /** Show a hover tooltip. Default true. */
  showTooltip?: boolean;
  /** Smooth the line with cubic Bézier segments. Default true. */
  curve?: boolean;
  /** Fill the area under the line. Default false. */
  fill?: boolean;
  className?: string;
  ariaLabel?: string;
}

const PAD = { top: 16, right: 16, bottom: 30, left: 44 };
const VIEWBOX_WIDTH = 600;

export function LineChart({
  data,
  height = 300,
  color = "primary",
  showGrid = true,
  showAxes = true,
  showPoints = false,
  showTooltip = true,
  curve = true,
  fill = false,
  className,
  ariaLabel = "Line chart",
}: LineChartProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [hover, setHover] = useState<number | null>(null);

  if (!data || data.length === 0) return null;

  const innerW = VIEWBOX_WIDTH - PAD.left - PAD.right;
  const innerH = height - PAD.top - PAD.bottom;
  const baseline = PAD.top + innerH;

  const values = data.map((d) => d.y);
  const minValue = Math.min(...values, 0);
  const maxValue = Math.max(...values);
  const pad = (maxValue - minValue) * 0.1 || 1;
  const domainMin = minValue - pad;
  const domainMax = maxValue + pad;

  const yScale = linearScale([domainMin, domainMax], [innerH, 0]);
  const xAt = (i: number) =>
    PAD.left +
    (data.length > 1 ? (i / (data.length - 1)) * innerW : innerW / 2);

  const points: Point[] = data.map((d, i) => ({ x: xAt(i), y: yScale(d.y) }));
  const linePath = curve ? smoothPath(points) : polylinePath(points);
  const areaPath =
    fill && points.length > 1
      ? `${linePath} L ${points[points.length - 1].x} ${baseline} L ${points[0].x} ${baseline} Z`
      : "";

  const ticks = niceTicks(domainMin, domainMax, 5);

  const handleMove = (e: ReactMouseEvent<SVGSVGElement>) => {
    if (!showTooltip) return;
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return;
    const localX = ((e.clientX - rect.left) / rect.width) * VIEWBOX_WIDTH;
    let nearest = 0;
    let best = Infinity;
    points.forEach((p, i) => {
      const dist = Math.abs(p.x - localX);
      if (dist < best) {
        best = dist;
        nearest = i;
      }
    });
    setHover(nearest);
  };

  const hovered = hover !== null ? points[hover] : null;
  const hoveredRaw = hover !== null ? data[hover] : null;

  return (
    <div
      className={["chart", `chart-${color}`, className]
        .filter(Boolean)
        .join(" ")}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${height}`}
        role="img"
        aria-label={ariaLabel}
        onMouseMove={handleMove}
        onMouseLeave={() => setHover(null)}>
        <title>{ariaLabel}</title>
        {showGrid && (
          <g className="chart-grid">
            {ticks.map((t) => (
              <line
                key={t}
                x1={PAD.left}
                x2={VIEWBOX_WIDTH - PAD.right}
                y1={yScale(t)}
                y2={yScale(t)}
              />
            ))}
          </g>
        )}
        {fill && areaPath && <path className="chart-area" d={areaPath} />}
        <path className="chart-line" d={linePath} />
        {showPoints &&
          points.map((p, i) => (
            <circle key={i} className="chart-point" cx={p.x} cy={p.y} r={3.5} />
          ))}
        {showAxes && (
          <g className="chart-axis">
            {ticks.map((t) => (
              <text key={t} x={PAD.left - 8} y={yScale(t) + 4} textAnchor="end">
                {t}
              </text>
            ))}
            {data.map((d, i) => (
              <text
                key={`${d.x}-${i}`}
                x={xAt(i)}
                y={height - 8}
                textAnchor="middle">
                {d.x}
              </text>
            ))}
          </g>
        )}
        {showTooltip && hovered && (
          <>
            <line
              className="chart-hover-line"
              x1={hovered.x}
              x2={hovered.x}
              y1={PAD.top}
              y2={baseline}
            />
            <circle
              className="chart-hover-point"
              cx={hovered.x}
              cy={hovered.y}
              r={5}
            />
          </>
        )}
      </svg>
      {showTooltip && hovered && hoveredRaw && (
        <div
          className="chart-tooltip"
          style={{
            left: `${(hovered.x / VIEWBOX_WIDTH) * 100}%`,
            top: `${(hovered.y / height) * 100}%`,
          }}>
          <span className="chart-tooltip-label">{hoveredRaw.x}</span>
          <span className="chart-tooltip-value">{hoveredRaw.y}</span>
        </div>
      )}
    </div>
  );
}
