import {
  forwardRef,
  useCallback,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import "./SegmentedControl.css";

export interface SegmentedOption {
  value: string;
  label: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
}

export type SegmentedControlSize = "sm" | "md" | "lg";

export interface SegmentedControlProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  options: SegmentedOption[];
  /** Controlled active value. */
  value?: string;
  /** Uncontrolled initial value. */
  defaultValue?: string;
  /** Fired when the active segment changes. */
  onChange?: (value: string) => void;
  size?: SegmentedControlSize;
  /** Stretch segments to fill the full width. */
  block?: boolean;
}

/**
 * A grouped set of mutually exclusive options (segmented control / toggle
 * group). Controlled + uncontrolled, keyboard accessible, theme-aware.
 */
export const SegmentedControl = forwardRef<
  HTMLDivElement,
  SegmentedControlProps
>(function SegmentedControl(
  {
    options,
    value,
    defaultValue = "",
    onChange,
    size = "md",
    block = false,
    className,
    ...props
  },
  ref,
) {
  const [internal, setInternal] = useState(defaultValue);
  const isControlled = value !== undefined;
  const active = isControlled ? value : internal;

  const handleSelect = useCallback(
    (next: string) => {
      if (!isControlled) setInternal(next);
      onChange?.(next);
    },
    [isControlled, onChange],
  );

  const classes = [
    "segmented",
    `segmented-${size}`,
    block ? "segmented-block" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div
      ref={ref}
      role="radiogroup"
      aria-label="Segmented control"
      className={classes}
      {...props}>
      {options.map((opt) => {
        const selected = active === opt.value;
        return (
          <button
            key={opt.value}
            type="button"
            role="radio"
            aria-checked={selected}
            disabled={opt.disabled}
            className={[
              "segmented-item",
              selected ? "segmented-item-active" : null,
            ]
              .filter(Boolean)
              .join(" ")}
            onClick={() => handleSelect(opt.value)}>
            {opt.icon ? (
              <span className="segmented-item-icon">{opt.icon}</span>
            ) : null}
            <span>{opt.label}</span>
          </button>
        );
      })}
    </div>
  );
});
