import { forwardRef, type HTMLAttributes } from "react";
import "./StatusDot.css";

export type StatusTone = "success" | "warning" | "danger" | "info" | "neutral";
export type StatusDotSize = "sm" | "md" | "lg";

export interface StatusDotProps extends HTMLAttributes<HTMLSpanElement> {
  tone?: StatusTone;
  size?: StatusDotSize;
  /** Show an expanding "pulse" ring. */
  pulse?: boolean;
  /** Accessible label. If omitted the dot is hidden from screen readers. */
  label?: string;
}

/** A small colored status indicator dot (optionally pulsing). */
export const StatusDot = forwardRef<HTMLSpanElement, StatusDotProps>(
  function StatusDot(
    {
      tone = "success",
      size = "md",
      pulse = false,
      label,
      className,
      ...props
    },
    ref,
  ) {
    const classes = [
      "status-dot",
      `status-dot-${tone}`,
      `status-dot-${size}`,
      pulse ? "status-dot-pulse" : null,
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <span
        ref={ref}
        className={classes}
        role={label ? "status" : undefined}
        aria-label={label}
        aria-hidden={label ? undefined : true}
        {...props}
      />
    );
  },
);
