import { useRef, useState, type MouseEvent as ReactMouseEvent } from "react";
import { linearScale, niceTicks } from "./scales";
import { ChartLegend } from "./ChartLegend";
import type { ChartColor, ChartSeries } from "./LineChart";

export interface GroupedBarChartProps {
  /** Multi-series data; each slot shows one bar per series side by side. */
  series: ChartSeries[];
  /** SVG viewBox height in units. Default 300. */
  height?: number;
  /** Show axis labels + grid lines. Default true. */
  showAxes?: boolean;
  /** Show the value on top of every bar. Default false. */
  showValues?: boolean;
  /** Rounded bar corners. Default true. */
  rounded?: boolean;
  /** Show a legend below the chart. Default true. */
  showLegend?: boolean;
  /** Show a hover tooltip. Default true. */
  showTooltip?: boolean;
  className?: string;
  ariaLabel?: string;
}

const PAD = { top: 16, right: 16, bottom: 30, left: 44 };
const VIEWBOX_WIDTH = 600;
const PALETTE: ChartColor[] = [
  "primary",
  "secondary",
  "success",
  "warning",
  "danger",
  "info",
  "dark",
  "light",
];

export function GroupedBarChart({
  series,
  height = 300,
  showAxes = true,
  showValues = false,
  rounded = true,
  showLegend = true,
  showTooltip = true,
  className,
  ariaLabel = "Grouped bar chart",
}: GroupedBarChartProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [hover, setHover] = useState<number | null>(null);

  if (!series || series.length === 0 || !series[0]?.data.length) return null;

  const count = series[0].data.length;
  const n = series.length;
  const innerW = VIEWBOX_WIDTH - PAD.left - PAD.right;
  const innerH = height - PAD.top - PAD.bottom;
  const maxValue = Math.max(
    ...series.flatMap((s) => s.data.map((d) => d.y)),
    0,
  );
  const domainMax = maxValue * 1.1 || 1;
  const yScale = linearScale([0, domainMax], [innerH, 0]);
  const baseline = height - PAD.bottom;

  const slotSize = innerW / count;
  const groupW = slotSize * 0.78;
  const gap = 3;
  const barW = (groupW - gap * (n - 1)) / n;
  const slotStart = (i: number) =>
    PAD.left + slotSize * i + (slotSize - groupW) / 2;

  const bars = series.map((sr, si) => {
    const color = sr.color ?? PALETTE[si % PALETTE.length];
    const r = rounded ? 4 : 0;
    return {
      name: sr.name,
      color,
      items: sr.data.map((d, i) => {
        const x = slotStart(i) + si * (barW + gap);
        const y = PAD.top + yScale(d.y);
        const h = baseline - y;
        return {
          key: `${sr.name}-${i}`,
          slot: i,
          x,
          y,
          w: barW,
          h,
          value: d.y,
          dPath: roundedTopRect(x, y, barW, h, r),
        };
      }),
    };
  });

  const ticks = niceTicks(0, domainMax, 5);

  const handleMove = (e: ReactMouseEvent<SVGSVGElement>) => {
    if (!showTooltip) return;
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return;
    const localX = ((e.clientX - rect.left) / rect.width) * VIEWBOX_WIDTH;
    const idx = Math.floor((localX - PAD.left) / slotSize);
    setHover(idx >= 0 && idx < count ? idx : null);
  };

  const hovered = hover !== null ? series[0].data[hover] : null;

  return (
    <div className={["chart", className].filter(Boolean).join(" ")}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${height}`}
        role="img"
        aria-label={ariaLabel}
        onMouseMove={handleMove}
        onMouseLeave={() => setHover(null)}>
        <title>{ariaLabel}</title>
        {showAxes && (
          <g className="chart-grid">
            {ticks.map((t) => (
              <line
                key={t}
                x1={PAD.left}
                x2={VIEWBOX_WIDTH - PAD.right}
                y1={PAD.top + yScale(t)}
                y2={PAD.top + yScale(t)}
              />
            ))}
          </g>
        )}
        <g className="chart-bars">
          {bars.map((sr) =>
            sr.items.map((b) => (
              <path
                key={b.key}
                className={[
                  "chart-bar",
                  `chart-${sr.color}`,
                  hover === b.slot ? "chart-bar-hover" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                d={b.dPath}
              />
            )),
          )}
        </g>
        {showAxes && (
          <g className="chart-axis">
            {ticks.map((t) => (
              <text
                key={t}
                x={PAD.left - 8}
                y={PAD.top + yScale(t) + 4}
                textAnchor="end">
                {t}
              </text>
            ))}
            {series[0].data.map((d, i) => (
              <text
                key={`${d.x}-${i}`}
                x={PAD.left + slotSize * i + slotSize / 2}
                y={height - 8}
                textAnchor="middle">
                {d.x}
              </text>
            ))}
          </g>
        )}
        {showValues &&
          bars.map((sr) =>
            sr.items.map((b) => (
              <text
                key={`v-${b.key}`}
                className="chart-bar-value"
                x={b.x + b.w / 2}
                y={b.y - 6}
                textAnchor="middle">
                {b.value}
              </text>
            )),
          )}
      </svg>
      {showLegend && (
        <ChartLegend
          series={bars.map((b) => ({ name: b.name, color: b.color }))}
        />
      )}
      {showTooltip && hovered && (
        <div
          className="chart-tooltip"
          style={{
            left: `${((PAD.left + slotSize * (hover ?? 0) + slotSize / 2) / VIEWBOX_WIDTH) * 100}%`,
            top: "10%",
          }}>
          <span className="chart-tooltip-label">{hovered.x}</span>
          <div className="chart-tooltip-rows">
            {bars.map((sr) => (
              <div key={sr.name} className="chart-tooltip-row">
                <span className={`chart-legend-swatch chart-${sr.color}`} />
                {sr.name}: {sr.items[hover ?? 0].value}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function roundedTopRect(
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): string {
  const rr = Math.min(r, w / 2, h);
  return `M ${x} ${y + h} L ${x} ${y + rr} Q ${x} ${y} ${x + rr} ${y} L ${x + w - rr} ${y} Q ${x + w} ${y} ${x + w} ${y + rr} L ${x + w} ${y + h} Z`;
}
