import { arcPath } from "./chartUtils";
import type { ChartColor } from "./LineChart";

export interface GaugeChartProps {
  value: number;
  /** Maximum value the gauge measures. Default 100. */
  max?: number;
  /** Square viewBox size in units. Default 200. */
  size?: number;
  /** Palette color used for the value arc. Default "primary". */
  color?: ChartColor;
  /** Arc stroke thickness. Default 16. */
  thickness?: number;
  /** Show the percentage centered below the arc. Default true. */
  showLabel?: boolean;
  className?: string;
  ariaLabel?: string;
}

const START_ANGLE = 180; // left
const END_ANGLE = 0; // right
const PAD = 24;

export function GaugeChart({
  value,
  max = 100,
  size = 200,
  color = "primary",
  thickness = 16,
  showLabel = true,
  className,
  ariaLabel = "Gauge chart",
}: GaugeChartProps) {
  if (max <= 0) return null;

  const clamped = Math.min(Math.max(value, 0), max);
  const pct = clamped / max;

  const cx = size / 2;
  const cy = size / 2;
  const r = size / 2 - PAD;
  const sweep = pct * 180;
  const endAngle = START_ANGLE - sweep;

  const trackPath = arcPath(cx, cy, r, START_ANGLE, END_ANGLE);
  const valuePath =
    sweep >= 0.01 ? arcPath(cx, cy, r, START_ANGLE, endAngle) : "";

  return (
    <div
      className={["chart", `chart-${color}`, className]
        .filter(Boolean)
        .join(" ")}>
      <svg viewBox={`0 0 ${size} ${size}`} role="img" aria-label={ariaLabel}>
        <title>{ariaLabel}</title>
        <path
          className="chart-gauge-track"
          d={trackPath}
          strokeWidth={thickness}
        />
        {valuePath && (
          <path
            className="chart-gauge-value"
            d={valuePath}
            strokeWidth={thickness}
          />
        )}
        {showLabel && (
          <text
            className="chart-gauge-label"
            x={cx}
            y={cy + 8}
            textAnchor="middle">
            {Math.round(pct * 100)}%
          </text>
        )}
      </svg>
    </div>
  );
}
