import {
  useEffect,
  useId,
  useRef,
  useState,
  forwardRef,
  HTMLAttributes,
  ReactNode,
} from "react";

export type ModalSize = "default" | "small" | "large";
export type ModalTransition =
  | "fade"
  | "scale"
  | "slide-up"
  | "slide-down"
  | "slide-left"
  | "slide-right";

export interface ModalProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "title"
> {
  open: boolean;
  onClose?: () => void;
  title?: ReactNode;
  footer?: ReactNode;
  size?: ModalSize;
  transition?: ModalTransition;
  transitionDuration?: number;
}

const sizeClass = (size: ModalSize | undefined) => {
  const s = size ?? "default";
  switch (s) {
    case "small":
      return "modal-sm";
    case "large":
      return "modal-lg";
    case "default":
    default:
      return "modal-md";
  }
};

export const Modal = forwardRef<HTMLDivElement, ModalProps>(function Modal(
  {
    open,
    onClose,
    title,
    footer,
    size = "default",
    transition = "fade",
    transitionDuration = 200,
    className,
    children,
    ...props
  },
  ref,
) {
  const titleId = useId();
  const [rendered, setRendered] = useState<boolean>(open);
  const [exiting, setExiting] = useState<boolean>(false);
  const exitTimer = useRef<number | null>(null);
  const [entering, setEntering] = useState<boolean>(false);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose?.();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  // Mount/unmount with exit animation support
  useEffect(() => {
    if (open) {
      setRendered(true);
      setExiting(false);
      setEntering(true);
      // Double rAF: the first fires before the browser paints, so a single
      // rAF would remove `is-entering` before the hidden state was ever drawn
      // and no CSS transition would run. A second rAF guarantees the browser
      // paints the initial hidden state, then animates to visible.
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setEntering(false);
        });
      });
      if (exitTimer.current) {
        window.clearTimeout(exitTimer.current);
        exitTimer.current = null;
      }
    } else if (rendered) {
      setExiting(true);
      if (exitTimer.current) window.clearTimeout(exitTimer.current);
      exitTimer.current = window.setTimeout(() => {
        setRendered(false);
        setExiting(false);
        exitTimer.current = null;
      }, transitionDuration);
    }
    return () => {
      if (exitTimer.current) {
        window.clearTimeout(exitTimer.current);
        exitTimer.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, transitionDuration]);

  if (!rendered) return null;

  const rootCls = [
    "modal",
    sizeClass(size),
    `modal-fx-${transition}`,
    exiting ? "is-exiting" : entering ? "is-entering" : null,
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const handleOverlayClick = () => onClose?.();
  const stop = (e: React.MouseEvent) => e.stopPropagation();

  return (
    <div
      className={rootCls}
      ref={ref}
      role="dialog"
      aria-modal="true"
      aria-labelledby={title ? titleId : undefined}
      data-state={exiting ? "exit" : "enter"}
      style={{
        // @ts-ignore custom CSS var for durations
        "--ui-modal-duration": `${transitionDuration}ms`,
      }}
      {...props}>
      <div className="modal-overlay" onClick={handleOverlayClick}>
        <div className="modal-content" onClick={stop}>
          {title ? (
            <div className="modal-header">
              <div className="modal-title" id={titleId}>
                {title}
              </div>
              {onClose ? (
                <button
                  type="button"
                  className="modal-close"
                  aria-label="Close"
                  onClick={onClose}>
                  ×
                </button>
              ) : null}
            </div>
          ) : onClose ? (
            <button
              type="button"
              className="modal-close modal-close-noheader"
              aria-label="Close"
              onClick={onClose}>
              ×
            </button>
          ) : null}
          <div className="modal-body">{children}</div>
          {footer ? <div className="modal-footer">{footer}</div> : null}
        </div>
      </div>
    </div>
  );
});
