import {
  forwardRef,
  useState,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  type Ref,
} from "react";
import "./Tag.css";

export type TagColor =
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "danger"
  | "info"
  | "dark"
  | "light";
export type TagSize = "sm" | "md" | "lg";
export type TagVariant = "filled" | "outline" | "soft";

export interface TagProps extends Omit<
  HTMLAttributes<HTMLSpanElement>,
  "onChange"
> {
  color?: TagColor;
  size?: TagSize;
  variant?: TagVariant;
  icon?: ReactNode;
  removable?: boolean;
  onRemove?: () => void;
  selectable?: boolean;
  selected?: boolean;
  defaultSelected?: boolean;
  onChange?: (selected: boolean) => void;
  className?: string;
  children?: ReactNode;
}

const colorClasses: Record<TagColor, string> = {
  primary: "tag-primary",
  secondary: "tag-secondary",
  success: "tag-success",
  warning: "tag-warning",
  danger: "tag-danger",
  info: "tag-info",
  dark: "tag-dark",
  light: "tag-light",
};

export const Tag = forwardRef<HTMLSpanElement, TagProps>(function Tag(
  {
    color = "secondary",
    size = "md",
    variant = "filled",
    icon,
    removable = false,
    onRemove,
    selectable = false,
    selected,
    defaultSelected = false,
    onChange,
    className,
    children,
    ...props
  },
  ref,
) {
  const [internalSelected, setInternalSelected] = useState(defaultSelected);
  const isControlled = selected !== undefined;
  const isSelected = isControlled ? selected : internalSelected;

  const baseClasses = [
    "tag",
    colorClasses[color],
    `tag-${size}`,
    `tag-${variant}`,
    selectable ? "tag-selectable" : "",
    selectable && isSelected ? "tag-selected" : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const handleToggle = () => {
    const next = !isSelected;
    if (!isControlled) setInternalSelected(next);
    onChange?.(next);
  };

  const handleRemove = (e: MouseEvent) => {
    e.stopPropagation();
    onRemove?.();
  };

  const sharedContent = (
    <>
      {selectable && isSelected ? (
        <span className="tag-check" aria-hidden="true">
          ✓
        </span>
      ) : null}
      {icon ? <span className="tag-icon">{icon}</span> : null}
      <span className="tag-label">{children}</span>
    </>
  );

  if (selectable) {
    return (
      <button
        ref={ref as unknown as Ref<HTMLButtonElement>}
        type="button"
        role="switch"
        aria-checked={isSelected}
        className={baseClasses}
        {...(props as HTMLAttributes<HTMLButtonElement>)}
        onClick={handleToggle}>
        {sharedContent}
      </button>
    );
  }

  return (
    <span ref={ref} className={baseClasses} {...props}>
      {sharedContent}
      {removable ? (
        <button
          type="button"
          className="tag-remove"
          aria-label="Remove tag"
          onClick={handleRemove}>
          ×
        </button>
      ) : null}
    </span>
  );
});
